WITH "r0" AS ( SELECT "s".* FROM "public"."article" AS "s" WHERE true AND ( EXISTS (SELECT 1 FROM "public"."author" AS "e0" WHERE true AND "e0"."id" = "s"."author_id" AND ( "e0"."name" = $1 )) ) ORDER BY "s"."id" ASC NULLS LAST ) SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "c1"."j" AS "author" ) AS "%")) ORDER BY "t0"."id" ASC NULLS LAST ), '[]') FROM "r0" AS "t0" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "t1"."name" AS "name" ) AS "%")) AS "j" FROM ( SELECT "s".* FROM "public"."author" AS "s" WHERE true AND "s"."id" = "t0"."author_id" AND ( ( true ) ) LIMIT 1 ) AS "t1" ) AS "c1" ON true
